-- 528: Original BrillaPrep NSMQ subj_nsmq_biology speed_race beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_528_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_528_guard;
INSERT INTO _migration_528_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_sr_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_bio_physiology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Name the type of blood vessel that carries blood away from the heart.' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Arteries' AND q.explanation IS 'Arteries carry blood away from the heart under high pressure and have thick, elastic, muscular walls to withstand it. Veins return blood to the heart, and capillaries link the two in the tissues.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_sr_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_528_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_sr_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_bio_genetics' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which molecule carries the genetic code from the nucleus to the ribosomes during protein synthesis?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Messenger RNA (mRNA)' AND q.explanation IS 'Messenger RNA is transcribed from a DNA template in the nucleus and travels to the ribosomes, where its codons are translated into an amino-acid sequence. Transfer RNA then brings the matching amino acids.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_sr_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_528_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_sr_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_bio_ecology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What term describes all the populations of different species living together in the same area?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'A community' AND q.explanation IS 'A community is the sum of all populations of different species in a habitat. A population is one species only, while an ecosystem adds the non-living (abiotic) environment to the community.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_sr_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_528_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_sr_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_bio_cells' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which cell structure controls the movement of substances into and out of the cell?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'The cell membrane' AND q.explanation IS 'The partially permeable cell (plasma) membrane surrounds every cell and regulates the entry and exit of substances by diffusion, osmosis and active transport. The cell wall of plant cells is fully permeable and only provides support.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_sr_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_bio_sr_b002_001', 'topic_nsmq_bio_physiology', 'subj_nsmq_biology', 'exam_nsmq', NULL, NULL, 'Name the type of blood vessel that carries blood away from the heart.', 'direct_answer', 'speed_race', NULL, 'Arteries', 'Arteries carry blood away from the heart under high pressure and have thick, elastic, muscular walls to withstand it. Veins return blood to the heart, and capillaries link the two in the tissues.', 'easy', '2', '1', '15', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, NULL);
