INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-002', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_bio_sr_b002_001', 'q_nsmq_bio_sr_b002_002', 'q_nsmq_bio_sr_b002_003', 'q_nsmq_bio_sr_b002_004');
